class QuadTree {
  constructor(bounds, capacity = 4) {
    this.bounds = bounds; // { x, y, w, h }
    this.capacity = capacity;
    this.points = [];
    this.children = null; // becomes [NW, NE, SW, SE] once split
  }

  insert(point) {
    if (!this.contains(point)) return false;

    if (!this.children && this.points.length < this.capacity) {
      this.points.push(point);
      return true;
    }

    if (!this.children) this.subdivide();

    return this.children.some(child => child.insert(point));
  }

  subdivide() {
    const { x, y, w, h } = this.bounds;
    const hw = w / 2, hh = h / 2;
    this.children = [
      new QuadTree({ x, y, w: hw, h: hh }, this.capacity),         // NW
      new QuadTree({ x: x + hw, y, w: hw, h: hh }, this.capacity), // NE
      new QuadTree({ x, y: y + hh, w: hw, h: hh }, this.capacity), // SW
      new QuadTree({ x: x + hw, y: y + hh, w: hw, h: hh }, this.capacity), // SE
    ];
    for (const pt of this.points) this.children.some(c => c.insert(pt));
    this.points = [];
  }
}

